import { SDK_SERVER_ERROR_CODES } from '../../schemas/sdk-errors-server.js';
import { SDK_CLIENT_ERROR_CODES } from '../../schemas/sdk-errors-client.js';
import { REGISTRY_ERROR_CODES } from '../../schemas/sdk-errors-registry.js';
function sortedEntries(record) {
    const entries = Object.entries(record);
    entries.sort(function (a, b) {
        return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0;
    });
    return Object.fromEntries(entries);
}
export function buildErrorCodes() {
    return {
        server: sortedEntries(SDK_SERVER_ERROR_CODES),
        client: sortedEntries(SDK_CLIENT_ERROR_CODES),
        registry: sortedEntries(REGISTRY_ERROR_CODES)
    };
}
